#!/usr/bin/env Rscript
# GSE154778 single-cell PSPS evidence upgrade: UCell, pseudobulk and mixed models.
suppressPackageStartupMessages({library(UCell); library(data.table); library(dplyr); library(tidyr); library(ggplot2); library(lme4)})
root <- normalizePath('.', mustWork=TRUE)
in_dir <- file.path(root,'results','sc_location_GSE154778'); out <- file.path(in_dir,'upgrade'); dir.create(out,recursive=TRUE,showWarnings=FALSE); fig <- file.path(out,'figures'); dir.create(fig,recursive=TRUE,showWarnings=FALSE)
core <- c('TXNIP','NLRP3','CASP1','GSDMD','IL1B','IL18')
extended <- unique(c(core,'CASP4','CASP5','PYCARD','AIM2','NLRC4','NLRP1','GSDME','GBP1','GBP5'))
features <- list(PSPS_core=core, pyroptosis_extended=extended)
matrix_file <- file.path(root,'data','raw','GSE154778','GSE154778_dgeMtx.csv.gz')
counts <- as.matrix(fread(matrix_file,data.table=FALSE,check.names=FALSE,showProgress=FALSE,encoding='UTF-8'))
gene_col <- colnames(counts)[1]; rownames(counts) <- toupper(sub('\\..*$','',counts[,gene_col])); counts <- counts[,-1,drop=FALSE]; mode(counts) <- 'numeric'
if(anyDuplicated(rownames(counts))) counts <- rowsum(counts,group=rownames(counts),reorder=FALSE)
meta0 <- fread(file.path(in_dir,'per_cell_scores.csv'),data.table=FALSE,check.names=FALSE,encoding='UTF-8'); cell_id_col <- if('Unnamed: 0' %in% names(meta0)) 'Unnamed: 0' else names(meta0)[1]
meta <- meta0; meta$cell_id <- as.character(meta[[cell_id_col]]); meta <- meta %>% select(-all_of(cell_id_col)); rownames(meta) <- meta$cell_id
common <- intersect(colnames(counts),meta$cell_id); if(length(common)<1000) stop('Too few cells matched between counts and metadata'); counts <- counts[,common,drop=FALSE]; meta <- meta[common,,drop=FALSE]
meta$cell_type <- as.character(meta$cell_type); meta$sample_id <- as.character(meta$sample_id); meta$sample_class <- factor(ifelse(grepl('^MET',meta$sample_id),'metastatic','primary'),levels=c('primary','metastatic')); meta$low_information <- as.logical(meta$low_information)
present_core <- intersect(core,rownames(counts)); present_extended <- intersect(extended,rownames(counts)); if(length(present_core)<4) stop('Fewer than four PSPS core genes present'); features <- list(PSPS_core=present_core,pyroptosis_extended=present_extended)
message('Running UCell on ',nrow(counts),' genes x ',ncol(counts),' cells')
uc <- ScoreSignatures_UCell(matrix=counts,features=features,maxRank=min(1500L,nrow(counts)),chunk.size=200L,ncores=1L,ties.method='average'); uc <- as.data.frame(uc); if(!all(rownames(uc) %in% meta$cell_id)) rownames(uc) <- colnames(counts); uc <- uc[meta$cell_id,,drop=FALSE]
meta$PSPS_UCell <- as.numeric(uc[meta$cell_id,'PSPS_core_UCell']); meta$pyroptosis_extended_UCell <- as.numeric(uc[meta$cell_id,'pyroptosis_extended_UCell']); meta$PSPS_original <- as.numeric(meta0$PSPS_core[match(meta$cell_id,as.character(meta0[[cell_id_col]]))])
per_cell <- meta %>% select(cell_id,sample_id,sample_class,cell_type,assignment_margin,low_information,PSPS_UCell,pyroptosis_extended_UCell,PSPS_original); write.csv(per_cell,file.path(out,'per_cell_ucell_scores.csv'),row.names=FALSE)
write.csv(data.frame(signature=names(features),n_genes=lengths(features),genes=sapply(features,paste,collapse=';')),file.path(out,'ucell_gene_sets.csv'),row.names=FALSE)
score_threshold <- as.numeric(quantile(per_cell$PSPS_UCell,.90,na.rm=TRUE))
summary_ct <- per_cell %>% group_by(cell_type) %>% summarise(n_cells=n(),n_samples=n_distinct(sample_id),mean_PSPS_UCell=mean(PSPS_UCell,na.rm=TRUE),median_PSPS_UCell=median(PSPS_UCell,na.rm=TRUE),q90_PSPS_UCell=as.numeric(quantile(PSPS_UCell,.90,na.rm=TRUE)),mean_extended_UCell=mean(pyroptosis_extended_UCell,na.rm=TRUE),frac_high_PSPS_UCell=mean(PSPS_UCell>=score_threshold,na.rm=TRUE),frac_low_information=mean(low_information,na.rm=TRUE),.groups='drop') %>% arrange(desc(mean_PSPS_UCell)); write.csv(summary_ct,file.path(out,'cell_type_ucell_summary.csv'),row.names=FALSE)
high_conf <- per_cell %>% filter(is.finite(assignment_margin), assignment_margin >= 0.1)
summary_high_conf <- high_conf %>% group_by(cell_type) %>% summarise(n_cells=n(),n_samples=n_distinct(sample_id),mean_PSPS_UCell=mean(PSPS_UCell,na.rm=TRUE),median_PSPS_UCell=median(PSPS_UCell,na.rm=TRUE),mean_extended_UCell=mean(pyroptosis_extended_UCell,na.rm=TRUE),.groups='drop') %>% arrange(desc(mean_PSPS_UCell)); write.csv(summary_high_conf,file.path(out,'cell_type_ucell_summary_margin_ge_0.1.csv'),row.names=FALSE)
epithelial_compartment <- per_cell %>% mutate(cell_type_group=ifelse(cell_type %in% c('epithelial_tumor','ductal'),'epithelial_compartment',cell_type)) %>% group_by(cell_type_group) %>% summarise(n_cells=n(),n_samples=n_distinct(sample_id),mean_PSPS_UCell=mean(PSPS_UCell,na.rm=TRUE),median_PSPS_UCell=median(PSPS_UCell,na.rm=TRUE),mean_extended_UCell=mean(pyroptosis_extended_UCell,na.rm=TRUE),.groups='drop') %>% arrange(desc(mean_PSPS_UCell)); write.csv(epithelial_compartment,file.path(out,'cell_type_ucell_summary_epithelial_compartment.csv'),row.names=FALSE)
ref <- 'macrophage'; cell_types <- unique(per_cell$cell_type); pair_tests <- bind_rows(lapply(setdiff(cell_types,ref),function(ct){a<-per_cell$PSPS_UCell[per_cell$cell_type==ref]; b<-per_cell$PSPS_UCell[per_cell$cell_type==ct]; wt<-suppressWarnings(wilcox.test(a,b,exact=FALSE)); data.frame(reference=ref,comparison=ct,n_reference=length(a),n_comparison=length(b),median_reference=median(a,na.rm=TRUE),median_comparison=median(b,na.rm=TRUE),difference_median=median(a,na.rm=TRUE)-median(b,na.rm=TRUE),p_value=wt$p.value)})); pair_tests$BH_FDR <- p.adjust(pair_tests$p_value,'BH'); write.csv(pair_tests,file.path(out,'cell_type_ucell_pairwise_tests.csv'),row.names=FALSE)
cell_keep <- per_cell %>% count(sample_id,cell_type,name='n_cells') %>% filter(n_cells>=10); per_keep <- per_cell %>% semi_join(cell_keep,by=c('sample_id','cell_type')); keep_ids <- per_keep$cell_id; counts_k <- counts[,keep_ids,drop=FALSE]
key <- interaction(per_keep$sample_id,per_keep$cell_type,drop=TRUE,sep='|||',lex.order=TRUE); agg <- t(rowsum(t(counts_k),group=key,reorder=FALSE)); unit_key <- colnames(agg); parts <- strsplit(unit_key,'\\|\\|\\|'); unit_meta <- data.frame(sample_id=sapply(parts,function(x)x[[1]]),cell_type=sapply(parts,function(x)x[[2]]),stringsAsFactors=FALSE); rownames(unit_meta)<-unit_key; unit_meta <- unit_meta %>% left_join(cell_keep,by=c('sample_id','cell_type')); agg <- agg[intersect(rownames(agg),rownames(counts)),,drop=FALSE]
pb_uc <- ScoreSignatures_UCell(matrix=agg,features=features,maxRank=min(1500L,nrow(agg)),chunk.size=200L,ncores=1L,ties.method='average'); pb_uc <- as.data.frame(pb_uc)[unit_key,,drop=FALSE]; lib <- colSums(agg); logcpm <- log1p(sweep(agg,2,pmax(lib,1),'/')*1e4); core_pb <- intersect(core,rownames(logcpm)); ext_pb <- intersect(extended,rownames(logcpm))
pb <- unit_meta %>% mutate(sample_class=factor(ifelse(grepl('^MET',sample_id),'metastatic','primary'),levels=c('primary','metastatic')),PSPS_UCell=as.numeric(pb_uc[unit_key,'PSPS_core_UCell']),pyroptosis_extended_UCell=as.numeric(pb_uc[unit_key,'pyroptosis_extended_UCell']),PSPS_logCPM=colMeans(logcpm[core_pb,,drop=FALSE]),extended_logCPM=colMeans(logcpm[ext_pb,,drop=FALSE])); write.csv(pb,file.path(out,'sample_celltype_pseudobulk_psps.csv'),row.names=FALSE)
pair_types <- c('epithelial_tumor','ductal','stellate','acinar')
pairwise <- bind_rows(lapply(pair_types,function(ct){m <- pb %>% filter(cell_type=='macrophage') %>% select(sample_id,macrophage_UCell=PSPS_UCell); c <- pb %>% filter(cell_type==ct) %>% select(sample_id,comparator_UCell=PSPS_UCell); z <- inner_join(m,c,by='sample_id') %>% mutate(difference=macrophage_UCell-comparator_UCell); if(!nrow(z)) return(NULL); data.frame(comparison=ct,n_paired=nrow(z),n_macrophage_higher=sum(z$difference>0),fraction_macrophage_higher=mean(z$difference>0),median_difference=median(z$difference),mean_difference=mean(z$difference))}))
write.csv(pairwise,file.path(out,'pseudobulk_paired_direction.csv'),row.names=FALSE)
fit_effects <- function(dat,response,model_name,min_cells=10){dat<-dat %>% filter(is.finite(.data[[response]]),n_cells>=min_cells); if(nrow(dat)<8 || n_distinct(dat$cell_type)<2 || n_distinct(dat$sample_id)<3) return(data.frame()); dat$cell_type<-factor(dat$cell_type); if(!(ref %in% levels(dat$cell_type))) return(data.frame()); dat$cell_type<-relevel(dat$cell_type,ref=ref); dat$sample_id<-factor(dat$sample_id); dat$sample_class<-factor(dat$sample_class,levels=c('primary','metastatic')); f <- if (n_distinct(dat$sample_class)>1) as.formula(paste(response,'~ cell_type + sample_class + (1|sample_id)')) else as.formula(paste(response,'~ cell_type + (1|sample_id)')); fit<-tryCatch(lmer(f,data=dat,REML=TRUE),error=function(e)NULL); if(is.null(fit)) return(data.frame()); co<-summary(fit)$coefficients; rn<-rownames(co); out<-bind_rows(lapply(setdiff(levels(dat$cell_type),ref),function(ct){term<-paste0('cell_type',ct); if(!(term %in% rn)) return(NULL); est<-co[term,'Estimate']; se<-co[term,'Std. Error']; data.frame(model=model_name,response=response,reference=ref,comparison=ct,n_units=nrow(dat),n_samples=n_distinct(dat$sample_id),macrophage_minus_comparison=-est,SE=se,CI_low=-est-1.96*se,CI_high=-est+1.96*se,p_value=2*pnorm(abs(est/se),lower.tail=FALSE))})); if(nrow(out)) out$BH_FDR<-p.adjust(out$p_value,'BH'); out}
cell_model_data <- per_cell %>% mutate(n_cells=1L); cell_models <- bind_rows(fit_effects(cell_model_data,'PSPS_UCell','single_cell_all',min_cells=1),fit_effects(cell_model_data %>% filter(!low_information),'PSPS_UCell','single_cell_exclude_low_information',min_cells=1),fit_effects(cell_model_data %>% filter(sample_class=='primary'),'PSPS_UCell','single_cell_primary_only',min_cells=1)); write.csv(cell_models,file.path(out,'mixed_model_celltype_effects.csv'),row.names=FALSE)
pb_models <- bind_rows(fit_effects(pb,'PSPS_UCell','pseudobulk_UCell'),fit_effects(pb,'PSPS_logCPM','pseudobulk_logCPM'),fit_effects(pb %>% filter(sample_class=='primary'),'PSPS_UCell','pseudobulk_UCell_primary_only')); write.csv(pb_models,file.path(out,'pseudobulk_celltype_effects.csv'),row.names=FALSE)
target_types <- c('macrophage','epithelial_tumor','acinar','ductal','stellate','beta')
consensus <- summary_ct %>% select(cell_type,mean_PSPS_UCell,median_PSPS_UCell,q90_PSPS_UCell,frac_high_PSPS_UCell,mean_extended_UCell,n_cells,n_samples) %>% mutate(rare_cell_type=n_cells<20 | n_samples<5,rank_mean=rank(-mean_PSPS_UCell,ties.method='average'),rank_median=rank(-median_PSPS_UCell,ties.method='average'),rank_q90=rank(-q90_PSPS_UCell,ties.method='average'),rank_high_fraction=rank(-frac_high_PSPS_UCell,ties.method='average'),rank_extended=rank(-mean_extended_UCell,ties.method='average'),consensus_rank=rowMeans(across(starts_with('rank_')),na.rm=TRUE)) %>% arrange(consensus_rank); write.csv(consensus,file.path(out,'sc_psps_source_consensus.csv'),row.names=FALSE)
major_consensus <- consensus %>% filter(cell_type %in% target_types) %>% arrange(consensus_rank); write.csv(major_consensus,file.path(out,'sc_psps_source_consensus_major_types.csv'),row.names=FALSE)
plot_dat <- per_cell %>% mutate(cell_type=reorder(cell_type,PSPS_UCell,FUN=median)); p1 <- ggplot(plot_dat,aes(cell_type,PSPS_UCell,fill=cell_type))+geom_violin(scale='width',trim=TRUE,alpha=.75,linewidth=.15)+geom_boxplot(width=.13,outlier.size=.1,fill='white')+geom_hline(yintercept=score_threshold,linetype=2,colour='grey35')+labs(x=NULL,y='PSPS UCell score',title='GSE154778: PSPS score distribution by cell type',subtitle=paste0('Dashed line: 90th percentile = ',round(score_threshold,3),'; score universe = ',nrow(counts),' genes'))+theme_bw(base_size=10)+theme(legend.position='none',axis.text.x=element_text(angle=45,hjust=1)); ggsave(file.path(fig,'single_cell_psps_source_violin.pdf'),p1,width=9,height=5.5); ggsave(file.path(fig,'single_cell_psps_source_violin.png'),p1,width=9,height=5.5,dpi=220)
forest_dat <- pb_models %>% filter(model %in% c('pseudobulk_UCell','pseudobulk_logCPM')) %>% mutate(label=paste(model,comparison,sep=': '),label=reorder(label,macrophage_minus_comparison)); if(nrow(forest_dat)){p2<-ggplot(forest_dat,aes(macrophage_minus_comparison,label,colour=model))+geom_vline(xintercept=0,linetype=2)+geom_errorbar(aes(xmin=CI_low,xmax=CI_high),orientation='y',height=.18,position=position_dodge(width=.4))+geom_point(position=position_dodge(width=.4),size=2)+labs(x='Macrophage minus comparator (estimate; 95% CI)',y=NULL,title='Pseudobulk mixed-model localization')+theme_bw(base_size=10); ggsave(file.path(fig,'single_cell_psps_source_forest.pdf'),p2,width=8.5,height=5.5); ggsave(file.path(fig,'single_cell_psps_source_forest.png'),p2,width=8.5,height=5.5,dpi=220)}
macro <- consensus %>% filter(cell_type==ref); rank1 <- if(nrow(major_consensus)) major_consensus$cell_type[1] else NA_character_; report <- c('# GSE154778 单细胞 PSPS 证据升级','',paste0('输入：',nrow(counts),' 个基因（完整矩阵按 canonical symbol 合并后），',ncol(counts),' 个细胞，',n_distinct(meta$sample_id),' 个样本（',sum(meta$sample_class=='primary'),' 个原发灶、',sum(meta$sample_class=='metastatic'),' 个转移灶）。'),'方法：使用 UCell 在完整表达矩阵的基因排序背景上对 PSPS_core（TXNIP/NLRP3/CASP1/GSDMD/IL1B/IL18）和扩展焦亡集合进行细胞级 rank-based 评分；随后以 sample_id×cell_type 聚合原始计数（每个单元至少 10 个细胞），并用样本随机截距混合模型比较细胞类型。','细胞类型标签来自既有 marker-module 推断；ductal 与 epithelial_tumor 的 marker 重叠较大，因此另行提供 assignment_margin≥0.1 和 epithelial compartment（ductal+epithelial_tumor）敏感性汇总。',' ',paste0('预设主要来源类型（巨噬、肿瘤上皮、腺泡、导管、星状、β）中，综合排序最高的是：',rank1,'；巨噬细胞细胞数=',macro$n_cells,'，样本数=',macro$n_samples,'，均值=',round(macro$mean_PSPS_UCell,4),'。β细胞仅7个、α细胞仅11个，均不作稳定来源判断。'),' ','解释边界：结果支持 PSPS 转录评分的候选细胞来源，不证明 caspase-1 活化、GSDMD 裂解或功能性焦亡。细胞级混合模型只作支持性敏感性分析；主推样本×细胞类型的 pseudobulk 结果及配对覆盖/方向。若巨噬细胞在 UCell、pseudobulk 和样本随机效应模型中保持较高且方向一致，可表述为“GSE154778 中 PSPS 转录评分主要富集于巨噬细胞，并得到多层次分析支持”；不能表述为巨噬细胞是唯一或已被功能验证的焦亡来源。',' ','输出文件：per_cell_ucell_scores.csv、cell_type_ucell_summary.csv、cell_type_ucell_summary_margin_ge_0.1.csv、cell_type_ucell_summary_epithelial_compartment.csv、sample_celltype_pseudobulk_psps.csv、pseudobulk_paired_direction.csv、mixed_model_celltype_effects.csv、pseudobulk_celltype_effects.csv、sc_psps_source_consensus.csv、sc_psps_source_consensus_major_types.csv，以及 figures/ 下的分布图和森林图。'); writeLines(report,file.path(out,'single_cell_upgrade_report_zh.md'),useBytes=TRUE); writeLines(capture.output(sessionInfo()),file.path(out,'sessionInfo.txt')); writeLines(c('method=UCell::ScoreSignatures_UCell',paste0('matrix=',matrix_file),paste0('score_gene_universe_n=',nrow(counts)),paste0('n_cells=',ncol(counts)),paste0('n_samples=',n_distinct(meta$sample_id)),'pseudobulk_min_cells=10','mixed_model=score ~ cell_type + sample_class + (1|sample_id)','cell_type_labels=existing marker-module assignments','interpretation=transcriptomic localization; not proof of functional pyroptosis'),file.path(out,'run_manifest.txt')); message('Completed GSE154778 single-cell PSPS evidence upgrade: ',out)
